/**
 * 「关键词派发」接口（SDK 侧绑定）。
 *
 * 实现只有一份：宿主注入运行时的 `window.otools.onOtoolsKeyword`（apiVersion >= 2）。
 * SDK 不再带本地兜底——两套实现并存会分叉，排查时很难分辨走的是哪套。
 *
 * 插件侧一行订阅：
 *
 *   import { onOtoolsKeyword } from "otools-plugin-sdk";
 *   const unlisten = await onOtoolsKeyword((items) => { ... });
 */

import type { KeywordListener } from './keyword-factory';

export {
  OTOOLS_KEYWORD_DISPATCH_EVENT,
  type OtoolsKeywordDispatch,
  type KeywordUnlisten,
} from './keyword-factory';

/** 订阅宿主派发的关键词，转发到 `window.otools.onOtoolsKeyword`。 */
export const onOtoolsKeyword: KeywordListener = (handler) => {
  const api = typeof window !== 'undefined' ? window.otools : undefined;
  if (typeof api?.onOtoolsKeyword !== 'function') {
    return Promise.reject(new Error('宿主未提供 onOtoolsKeyword（需要 apiVersion >= 2）'));
  }
  return api.onOtoolsKeyword(handler);
};
