/**
 * 「打开文件」接口（SDK 侧绑定）。
 *
 * 实现只有一份：宿主注入运行时的 `window.otools.onOtoolsOpenFile`（apiVersion >= 2）。
 *
 * 宿主侧链路：文件路径先排进按 pluginUuid 分桶的队列，再对插件 webview
 * `emit_to("otools-open-file")` 敲门；事件只做敲门，载荷一律通过
 * `otools_consume_open_files` 取走，所以插件先启动还是宿主先投递都不会丢件。
 */

import type { FileOpenListener } from './file-open-factory';

export {
  OTOOLS_FILE_DELIVER_EVENT,
  parseLaunchOpenFiles,
  toOpenFileEntries,
  type OtoolsOpenFileEntry,
  type FileOpenListener,
  type FileOpenUnlisten,
} from './file-open-factory';

/** 订阅宿主投递的文件，转发到 `window.otools.onOtoolsOpenFile`。 */
export const onOtoolsOpenFile: FileOpenListener = (handler) => {
  const api = typeof window !== 'undefined' ? window.otools : undefined;
  if (typeof api?.onOtoolsOpenFile !== 'function') {
    return Promise.reject(new Error('宿主未提供 onOtoolsOpenFile（需要 apiVersion >= 2）'));
  }
  return api.onOtoolsOpenFile(handler);
};
